 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The two equal-sized panels are separated by a uniform line.
    split = None
    axis = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r > 0 and h - r - 1 == r:
            split, axis = r, "row"
            break
    if split is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and c > 0 and w - c - 1 == c:
                split, axis = c, "col"
                break
    if axis == "row":
        a, b = grid[:split], grid[split + 1:]
    elif axis == "col":
        a = [row[:split] for row in grid]
        b = [row[split + 1:] for row in grid]
    else:
        raise ValueError("No centered separator found")

    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    # The shared background color is the sole color common to both panels.
    if len(common) != 1:
        # In case a panel contains extra noise colors, use the shared color
        # occurring most often in both panels combined.
        base = max(common, key=lambda v: sum(x == v for row in a for x in row) + sum(x == v for row in b for x in row))
    else:
        base = next(iter(common))
    out = [[3 if a[r][c] == base and b[r][c] == base else base
            for c in range(len(a[0]))] for r in range(len(a))]
    return out
